//! Checks the codec against the shared vectors in `card-spec/vectors/`.
//!
//! The vectors are generated by an independent Python implementation
//! (`card-spec/tools/generate_vectors.py`), so this test catches mistakes that
//! a round trip through our own encoder would hide.

// Test helpers outside `#[test]` functions: failing loudly is the point.
#![allow(clippy::unwrap_used, clippy::panic, clippy::similar_names)]

use std::fs;
use std::path::PathBuf;

use serde_json::Value;
use tapbox_card::{Card, Decoded, Origin, WebUrl, decode_tag, encode_tag};

fn vectors() -> Vec<(String, Value)> {
    let dir = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../card-spec/vectors");
    let mut vectors: Vec<_> = fs::read_dir(&dir)
        .unwrap_or_else(|e| panic!("reading {}: {e}", dir.display()))
        .map(|entry| {
            let path = entry.unwrap().path();
            let name = path.file_stem().unwrap().to_string_lossy().into_owned();
            let value = serde_json::from_str(&fs::read_to_string(&path).unwrap()).unwrap();
            (name, value)
        })
        .collect();
    vectors.sort_by(|a, b| a.0.cmp(&b.0));
    assert!(vectors.len() >= 9, "expected the full vector set");
    vectors
}

fn expected_card(expected: &Value) -> Card {
    let payload = serde_json::to_vec(&expected["payload"]).unwrap();
    Card::from_json(&payload).unwrap()
}

#[test]
fn decoder_matches_every_vector() {
    for (name, vector) in vectors() {
        let bytes = hex::decode(vector["tlv_hex"].as_str().unwrap()).unwrap();
        let expected = &vector["expected"];
        let decoded = decode_tag(&bytes);
        match expected["kind"].as_str().unwrap() {
            "card" => {
                let origin = match expected["origin"].as_str().unwrap() {
                    "tapbox" => Origin::Tapbox,
                    "uri-record" => Origin::UriRecord,
                    other => panic!("{name}: unknown origin {other}"),
                };
                assert_eq!(
                    decoded,
                    Ok(Decoded::Card {
                        card: expected_card(expected),
                        origin
                    }),
                    "{name}"
                );
            }
            "empty" => assert_eq!(decoded, Ok(Decoded::Empty), "{name}"),
            "unrecognized" => assert_eq!(decoded, Ok(Decoded::Unrecognized), "{name}"),
            "error" => assert!(
                decoded.is_err(),
                "{name}: expected an error, got {decoded:?}"
            ),
            other => panic!("{name}: unknown kind {other}"),
        }
    }
}

#[test]
fn encoder_matches_every_vector_that_specifies_it() {
    let mut checked = 0;
    for (name, vector) in vectors() {
        let Some(encoder) = vector.get("encoder") else {
            continue;
        };
        let landing = encoder["landing_page"]
            .as_str()
            .map(|url| WebUrl::parse(url).unwrap());
        let card = expected_card(&vector["expected"]);
        let encoded = encode_tag(&card, landing.as_ref()).unwrap();
        assert_eq!(
            hex::encode(encoded),
            vector["tlv_hex"].as_str().unwrap(),
            "{name}"
        );
        checked += 1;
    }
    assert!(checked >= 4);
}
